mapper.select:
SELECT
    metric_unit,
    CAST(COALESCE(SUM(delta_amount), 0) AS double precision) AS total_delta,
    COUNT(DISTINCT session_external_id) AS session_count
FROM provider_usage_records

    organization_uuid = #{query.OrganizationUUID}
    AND workspace_uuid = #{query.WorkspaceUUID}

        AND session_external_id IN #{sessionID}


        AND sampled_at >= #{query.Start}


        AND sampled_at < #{query.End}


GROUP BY metric_unit
ORDER BY metric_unit ASC
